"""Open one PR per x64 termsrv.dll build that Winbindex knows and rdpwrap.ini lacks.

--plan     (Linux)   list missing builds, drop the ones already handled, write `builds=<json>`
                     to $GITHUB_OUTPUT. Env: FINDER_VERSION, MAX_PRS (default 5), GH_TOKEN.
--offsets  for each planned build: download termsrv.dll from the Microsoft symbol server,
           check its sha256, run RDPWrapOffsetFinder.exe (under $WINE when set, e.g. on
           Linux), insert [ver] and [ver-SLInit] at their sorted positions, open a PR.
           Env: BUILDS, FINDER, WINE (optional), FINDER_VERSION, BASE, DRY_RUN, GH_TOKEN.
--rebase   re-create open auto/termsrv-* PRs that conflict with BASE (run after merges).
--test     offline self-check.

A build is skipped when an open PR (any author) covers it, or when an auto PR made with the
current RDPWrapOffsetFinder version exists in any state (closed = a human said no). A closed
auto PR from an older finder version only blocks the build if the new offsets are identical.
"""
import gzip
import hashlib
import json
import os
import re
import subprocess
import sys
import tempfile
import urllib.request

WINBINDEX = "https://winbindex.m417z.com/data/by_filename_compressed/termsrv.dll.json.gz"
MSDL = "https://msdl.microsoft.com/download/symbols/termsrv.dll/{ts:08X}{vsize:x}/termsrv.dll"
INI = "rdpwrap.ini"
AMD64 = 34404
HEADER = re.compile(r"^\[(\d+(?:\.\d+){3})(-SLInit)?\][^\n]*\n", re.M)
AUTO = re.compile(r"^auto/termsrv-(\d+(?:\.\d+){3})(?:-(v[\w.]+))?$")  # branch -> (build, finder version)


def vkey(v):
    return tuple(int(x) for x in v.split("."))


def title(ver, fv):
    return "Add support for %s (autogenerated by RDPWrapOffsetFinder %s)" % (ver, fv)


def sh(*cmd, check=True):
    return subprocess.run(cmd, check=check, capture_output=True, text=True).stdout.strip()


def fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent": "rdpwrap.ini-ci"})
    with urllib.request.urlopen(req, timeout=120) as r:
        return r.read()


def section(text, ver, slinit):
    """Body of [ver] or [ver-SLInit] (header included, trailing blank lines dropped)."""
    name = re.escape(ver + ("-SLInit" if slinit else ""))
    m = re.search(r"(?ms)^\[" + name + r"\][^\n]*\n.*?(?=^\[|\Z)", text)
    return m and m.group(0).rstrip() + "\n"


def norm(s):
    return "\n".join(line.rstrip() for line in (s or "").replace("\r", "").strip().splitlines())


def insert_sorted(ini, ver, body, slinit):
    """Insert body before the first same-kind header with a higher version, else after the last one."""
    group = [m for m in HEADER.finditer(ini) if bool(m.group(2)) == slinit]
    if not group:
        raise ValueError("no [x.y.z.w%s] sections in ini" % ("-SLInit" if slinit else ""))
    later = [m for m in group if vkey(m.group(1)) > vkey(ver)]
    if later:
        pos = later[0].start()
    else:  # after the last section of this kind = start of the next header, or EOF
        nxt = re.compile(r"^\[", re.M).search(ini, group[-1].end())
        pos = nxt.start() if nxt else len(ini)
        if not nxt and not ini.endswith("\n\n"):
            ini, pos = ini.rstrip("\n") + "\n\n", len(ini.rstrip("\n")) + 2
    return ini[:pos] + body + "\n" + ini[pos:]


def add_build(raw, ver, main, slinit):
    """rdpwrap.ini text with both sections inserted, keeping the file's own line endings (CRLF upstream)."""
    crlf = "\r\n" in raw
    new = insert_sorted(insert_sorted(raw.replace("\r\n", "\n"), ver, main, False), ver, slinit, True)
    return new.replace("\n", "\r\n") if crlf else new


def unknown_codes(body, ini):
    """*Code.x64/x86 values that [PatchCodes] does not define (needs a human)."""
    pc = re.search(r"(?ms)^\[PatchCodes\][^\n]*\n.*?(?=^\[|\Z)", ini).group(0)
    known = set(re.findall(r"^([^=\s]+)\s*=", pc, re.M))
    return sorted({c for c in re.findall(r"^\w+Code\.x(?:64|86)\s*=\s*(\S+)", body, re.M)} - known)


def read_ini():
    return open(INI, encoding="latin-1", newline="").read()


def show(ref):
    """rdpwrap.ini at a git ref, bytes-exact (keeps CRLF)."""
    return subprocess.run(["git", "show", ref + ":" + INI], check=True, capture_output=True).stdout.decode("latin-1")


def added_text(n):
    """The '+' lines of PR #n's diff, i.e. the sections it adds."""
    diff = sh("gh", "pr", "diff", str(n), check=False)
    return "\n".join(l[1:] for l in diff.splitlines() if l.startswith("+") and not l.startswith("+++"))


def decide(ver, fv, prs, open_adds):
    """(prev, None) to go ahead, prev = closed older-finder auto PRs to compare offsets with; (None, why) to skip.

    prs: [{number, state, title, headRefName}]; open_adds: {number: builds an open PR adds, from its diff}.
    """
    mention = re.compile(r"(?<![\d.])" + re.escape(ver) + r"(?!\d)")
    prev = []
    for p in prs:
        n, state = p["number"], p["state"]
        if state == "OPEN" and (mention.search(p["title"] + " " + p["headRefName"]) or ver in open_adds.get(n, ())):
            return None, "open PR #%d covers it" % n
        m = AUTO.match(p["headRefName"])
        if m and m.group(1) == ver:
            if m.group(2) == fv:
                return None, "auto PR #%d made with RDPWrapOffsetFinder %s is %s" % (n, fv, state.lower())
            if state == "CLOSED":
                prev.append(n)
    return prev, None


def missing_builds(ini):
    have = {m.group(1) for m in HEADER.finditer(ini) if not m.group(2)}
    data = json.loads(gzip.decompress(fetch(WINBINDEX)))
    builds = {}
    for fi in (e.get("fileInfo") or {} for e in data.values()):
        if fi.get("machineType") == AMD64 and "version" in fi and "timestamp" in fi:
            builds[fi["version"].split()[0]] = fi
    return [builds[v] for v in sorted(set(builds) - have, key=vkey, reverse=True)]


def plan():
    fv = os.environ["FINDER_VERSION"]
    limit = int(os.environ.get("MAX_PRS") or 5)
    todo_all = missing_builds(read_ini())
    print("Builds missing from %s: %s" % (INI, [f["version"].split()[0] for f in todo_all] or "none"))
    todo = []
    if todo_all:
        prs = json.loads(sh("gh", "pr", "list", "--state", "all", "--limit", "5000",
                            "--json", "number,state,title,headRefName"))
        # Open PRs are often titled just "Update rdpwrap.ini": look at what they add.
        open_adds = {p["number"]: set(re.findall(r"^\[([\d.]+)\]", added_text(p["number"]), re.M))
                     for p in prs if p["state"] == "OPEN"}
        for fi in todo_all:
            ver = fi["version"].split()[0]
            prev, why = decide(ver, fv, prs, open_adds)
            if why:
                print("[skip] %s: %s" % (ver, why))
            elif len(todo) >= limit:
                print("[skip] %s: MAX_PRS=%d reached" % (ver, limit))
            else:
                todo.append({"ver": ver, "sha256": fi["sha256"], "timestamp": fi["timestamp"],
                             "virtualSize": fi["virtualSize"], "prev": prev})
    print("Planned for RDPWrapOffsetFinder %s: %s" % (fv, [b["ver"] for b in todo] or "none"))
    if os.environ.get("GITHUB_OUTPUT"):
        with open(os.environ["GITHUB_OUTPUT"], "a") as f:
            f.write("builds=%s\n" % json.dumps(todo))


def find_offsets(finder, b):
    """Return ([ver], [ver-SLInit], url) from RDPWrapOffsetFinder, or a reason string."""
    ver = b["ver"]
    url = MSDL.format(ts=b["timestamp"], vsize=b["virtualSize"])
    try:
        dll = fetch(url)
    except Exception as e:  # noqa: BLE001 - any download failure just skips the build
        return "download failed: %s (%s)" % (e, url)
    if hashlib.sha256(dll).hexdigest() != b["sha256"]:
        return "sha256 mismatch for " + url
    with tempfile.TemporaryDirectory() as d:
        path = os.path.join(d, "termsrv.dll")
        open(path, "wb").write(dll)
        wine = os.environ.get("WINE")
        # Under Wine the .exe sees the Linux file system as drive Z:.
        cmd = [wine, finder, "Z:" + path.replace("/", "\\")] if wine else [finder, path]
        r = subprocess.run(cmd, capture_output=True)
    out = (r.stdout + r.stderr).decode("ascii", "replace").replace("\r\n", "\n")
    if "ERROR" in out or "Symbol not found" in out:
        return "OffsetFinder failed:\n" + out
    main, slinit = section(out, ver, False), section(out, ver, True)
    if not main or not slinit:
        return "OffsetFinder output lacks [%s] or [%s-SLInit]:\n%s" % (ver, ver, out)
    return main, slinit, url


def open_pr(ini, b, main, slinit, url, fv, base, dry):
    ver = b["ver"]
    branch = "auto/termsrv-%s-%s" % (ver, fv)
    if dry:
        print("[dry-run] would open '%s' on %s:\n%s\n%s" % (title(ver, fv), branch, main, slinit))
        return
    sh("git", "checkout", "-q", "-B", branch, "origin/" + base)
    open(INI, "w", encoding="latin-1", newline="").write(add_build(ini, ver, main, slinit))
    sh("git", "commit", "-q", "-am", title(ver, fv))
    sh("git", "push", "-q", "-f", "origin", branch)
    body = (
        "Autogenerated by `.github/workflows/new-termsrv-versions.yml`.\n\n"
        "- **termsrv.dll** `%s` x64, sha256 `%s` (matches [Winbindex](https://winbindex.m417z.com/?file=termsrv.dll)), "
        "from %s\n- **Offsets** by [RDPWrapOffsetFinder](https://github.com/llccd/RDPWrapOffsetFinder) %s\n"
        "- All patch codes used are already in `[PatchCodes]`.\n\n"
        "Not tested on a live system yet: please confirm on a machine with this build before merging. "
        "If you close this PR, it won't be opened again for this build until a newer RDPWrapOffsetFinder "
        "gives different offsets.\n\n```ini\n%s\n%s```\n" % (ver, b["sha256"], url, fv, main, slinit)
    )
    print(sh("gh", "pr", "create", "--base", base, "--head", branch, "--title", title(ver, fv), "--body", body))
    sh("git", "checkout", "-q", "origin/" + base)


def offsets():
    builds = json.loads(os.environ["BUILDS"])
    finder, fv = os.environ["FINDER"], os.environ["FINDER_VERSION"]
    base = os.environ.get("BASE", "master")
    dry = os.environ.get("DRY_RUN", "").lower() == "true"
    ini = read_ini()
    opened, failed = 0, []
    for b in builds:
        ver = b["ver"]
        res = find_offsets(finder, b)
        if isinstance(res, str):
            failed.append(ver)
            print("[fail] %s: %s" % (ver, res))
            continue
        main_s, slinit_s, url = res
        bad = unknown_codes(main_s, ini)
        if bad:
            failed.append(ver)
            print("[fail] %s: needs patch codes missing from [PatchCodes]: %s" % (ver, bad))
            continue
        new = (norm(main_s), norm(slinit_s))
        same = [n for n in b["prev"]
                if (norm(section(added_text(n), ver, False)), norm(section(added_text(n), ver, True))) == new]
        if same:
            print("[skip] %s: same offsets as closed PR #%d" % (ver, same[0]))
            continue
        open_pr(ini, b, main_s, slinit_s, url, fv, base, dry)
        opened += 1
    print("%s %d PR(s); no offsets for: %s" % ("Would open" if dry else "Opened", opened, failed or "none"))


def rebase_open_prs():
    """After a merge: re-create each open auto/termsrv-* PR that now conflicts, on top of the new base."""
    base = os.environ.get("BASE", "master")
    dry = os.environ.get("DRY_RUN", "").lower() == "true"
    sh("git", "fetch", "-q", "origin")
    prs = json.loads(sh("gh", "pr", "list", "--state", "open", "--limit", "200", "--json", "number,title,headRefName"))
    moved = False
    for p in prs:
        m = AUTO.match(p["headRefName"])
        if not m:
            continue
        branch, n, ver = p["headRefName"], p["number"], m.group(1)
        # merge-tree exits 1 on conflicts and changes nothing in the work tree.
        if subprocess.run(["git", "merge-tree", "--write-tree", "origin/" + base, "origin/" + branch],
                          capture_output=True).returncode == 0:
            print("[ok]   #%d %s merges cleanly" % (n, ver))
            continue
        base_ini, pr_ini = show("origin/" + base), show("origin/" + branch).replace("\r\n", "\n")
        if section(base_ini.replace("\r\n", "\n"), ver, False):
            print("[skip] #%d %s: [%s] is already on %s, close the PR" % (n, ver, ver, base))
            continue
        main_s, slinit_s = section(pr_ini, ver, False), section(pr_ini, ver, True)
        if not main_s or not slinit_s:
            print("[fail] #%d %s: branch lacks [%s] or [%s-SLInit]" % (n, ver, ver, ver))
            continue
        if dry:
            print("[dry-run] would rebase #%d %s onto %s" % (n, ver, base))
            continue
        sh("git", "checkout", "-q", "-B", branch, "origin/" + base)
        moved = True
        open(INI, "w", encoding="latin-1", newline="").write(add_build(base_ini, ver, main_s, slinit_s))
        sh("git", "commit", "-q", "-am", p["title"])
        sh("git", "push", "-q", "-f", "origin", branch)
        sha = sh("git", "rev-parse", "--short", "origin/" + base)
        sh("gh", "pr", "comment", str(n), "--body", "Rebased onto `%s` %s: it conflicted after a merge. Same offsets." % (base, sha))
        print("[done] #%d %s rebased onto %s %s" % (n, ver, base, sha))
    if moved:
        sh("git", "checkout", "-q", "origin/" + base)


def test():
    ini = ("[Main]\nUpdated=x\n\n[PatchCodes]\nnop=90\n\n"
           "[10.0.1.5]\nA=1\n\n[10.0.1.9]\nA=2\n\n[10.0.1.5-SLInit]\nB=1\n\n[10.0.1.9-SLInit]\nB=2\n")
    a = insert_sorted(ini, "10.0.1.7", "[10.0.1.7]\nA=3\n", False)
    a = insert_sorted(a, "10.0.1.7", "[10.0.1.7-SLInit]\nB=3\n", True)
    assert re.findall(r"^\[([^\]]+)\]", a, re.M) == ["Main", "PatchCodes", "10.0.1.5", "10.0.1.7", "10.0.1.9",
                                                     "10.0.1.5-SLInit", "10.0.1.7-SLInit", "10.0.1.9-SLInit"], a
    b = insert_sorted(ini, "10.0.2.1", "[10.0.2.1-SLInit]\nB=4\n", True)  # newest: appended at EOF
    assert b.endswith("[10.0.1.9-SLInit]\nB=2\n\n[10.0.2.1-SLInit]\nB=4\n\n"), repr(b[-60:])
    assert vkey("10.0.26100.32230") > vkey("10.0.26100.9818")  # numeric, not string, order
    out = "junk\n[10.0.1.7]\nX.x64=1\nLocalOnlyCode.x64=nop\nSingleUserCode.x64=newcode\n\n[10.0.1.7-SLInit]\nb=1\n"
    assert section(out, "10.0.1.7", False).startswith("[10.0.1.7]\n") and section(out, "10.0.1.7", True)
    assert unknown_codes(section(out, "10.0.1.7", False), ini) == ["newcode"]
    c = add_build(ini.replace("\n", "\r\n"), "10.0.1.7", "[10.0.1.7]\nA=3\n", "[10.0.1.7-SLInit]\nB=3\n")
    assert c.count("\n") == c.count("\r\n") and "[10.0.1.7]\r\nA=3\r\n" in c, "CRLF file must stay pure CRLF"
    assert "\r" not in add_build(ini, "10.0.1.7", "[10.0.1.7]\nA=3\n", "[10.0.1.7-SLInit]\nB=3\n")
    assert norm("[a]\r\nx=1  \r\n\r\n") == norm("[a]\nx=1\n")

    v = "10.0.26100.9818"
    pr = lambda n, state, t, head: {"number": n, "state": state, "title": t, "headRefName": head}
    human_open = pr(1, "OPEN", "Update rdpwrap.ini", "patch-4")
    human_closed = pr(2, "CLOSED", "Add support for " + v, "add-9818")
    auto_old_closed = pr(3, "CLOSED", title(v, "v0.9"), "auto/termsrv-%s-v0.9" % v)
    auto_cur_closed = pr(4, "CLOSED", title(v, "v1.0"), "auto/termsrv-%s-v1.0" % v)
    other = pr(5, "OPEN", title("10.0.26100.98", "v1.0"), "auto/termsrv-10.0.26100.98-v1.0")
    assert decide(v, "v1.0", [human_open], {1: {v}})[1] == "open PR #1 covers it"        # found via its diff
    assert decide(v, "v1.0", [human_open], {1: set()}) == ([], None)                     # unrelated open PR
    assert decide(v, "v1.0", [human_closed, other], {5: set()}) == ([], None)             # closed human PR, prefix build
    assert decide(v, "v1.0", [auto_old_closed], {}) == ([3], None)                        # older finder: retry, compare
    assert "v1.0 is closed" in decide(v, "v1.0", [auto_old_closed, auto_cur_closed], {})[1]  # current finder: rejected
    assert decide(v, "v1.1", [auto_old_closed, auto_cur_closed], {}) == ([3, 4], None)   # newer finder: retry
    assert AUTO.match("auto/termsrv-10.0.26100.9818").groups() == (v, None)              # pre-version branches
    print("self-test ok")


if __name__ == "__main__":
    mode = next((a for a in sys.argv[1:] if a.startswith("--")), "")
    {"--test": test, "--plan": plan, "--offsets": offsets, "--rebase": rebase_open_prs}[mode]()
